#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;

    // O(1) operations at both ends
    d.push_front(10);
    d.push_back(20);
    d.push_front(5);

    // Output: 5, 10, 20
    for (int x : d) {
        std::cout << x << " ";
    }
    std::cout << "\n";

    d.pop_front(); // O(1)
    d.pop_back();  // O(1)
    // Remaining: 10
}
